DEFAULT_FORECAST_LEDGER = ".vibey/delivery-estimates.jsonl"
DEFAULT_TEST_TIME_RECORD = "docs/runbooks/expansion/evidence/13-front1-validation.md"
DEFAULT_TIMEZONE = "America/New_York"
DEFAULT_SINCE = date(2026, 8, 9)
SCRIPT = "scripts/paper_figures.py"
PACKAGES: tuple[tuple[str, str], ...] = (
    ("vibey", "src/vibey"),
    ("vibey-gh", "src/vibey_tools/gh"),
    ("claudeloop", "src/vibey_runners/claude"),
    ("vibey-bootstrap", "src/vibey_tools/bootstrap"),
    ("agyloop", "src/vibey_runners/agy"),
    ("codexloop", "src/vibey_runners/codex"),
    ("cursorloop", "src/vibey_runners/cursor"),
    ("qwenloop", "src/vibey_runners/qwen"),
    ("vibey-skills", "src/vibey_tools/skills"),
    ("opencodeloop", "src/vibey_runners/opencode"),
    ("runners-common", "src/vibey_runners/common"),
)
LAYERS: tuple[str, ...] = ("domain", "application", "infrastructure", "cli", "tui")
TAG_PACKAGES: tuple[tuple[str, str], ...] = (
    ("vibey-v", "vibey"),
    ("claudeloop-v", "claudeloop"),
    ("agyloop-v", "agyloop"),
    ("cursorloop-v", "cursorloop"),
    ("v", "codexloop"),
)
_MARKER = re.compile(
    r"<!-- BEGIN GENERATED figure:(?P<name>[a-z0-9-]+) rev:(?P<rev>[0-9a-f]+) — regenerated by "
    + re.escape(SCRIPT)
    + r" -->\n(?P<body>.*?)<!-- END GENERATED figure:(?P=name) -->",
    re.DOTALL,
)
_TEST_DEF = re.compile(rb"^\s*(?:async\s+)?def test_", re.MULTILINE)
_FENCE = re.compile(r"^```latex\n(.*?)^```", re.DOTALL | re.MULTILINE)
_LABEL = re.compile(r"\\label\{(fig:[^}]+)\}")
_REF = re.compile(r"\[(?:Fig\.?|Figure)\s*\d*\]\(#(fig:[A-Za-z0-9:_-]+)\)")
_STREAM = re.compile(r"^(?P<at>\S+Z) (?P<verb>start|end)\s+(?P<lane>\S+)")
_PR_SUBJECT = re.compile(r"\(#\d+\)$")
_CC_TYPE = re.compile(r"^([a-z]+)(?:\([^)]*\))?!?:")


def _tex(text: str) -> str:
    """Escape the handful of characters that would break TeX inside a node label."""
    return (
        text.replace("\\", r"\textbackslash{}")
        .replace("&", r"\&")
        .replace("%", r"\%")
        .replace("#", r"\#")
        .replace("_", r"\_")
        .replace("$", r"\$")
    )


def _fmt(value: float, digits: int = 2) -> str:
    return f"{value:.{digits}f}"


def _thousands(value: int) -> str:
    return f"{value:,}"


