        layers = data["layers"]
        layer_coords = " ".join(f"({layers[layer]},{i})" for i, layer in enumerate(LAYERS))
        floors = {"domain", "application", "infrastructure", "cli"}
        # Plot c prints no value beside its bars: the line count rides inside the pill that
